#!/bin/sh
# Generated by reflex generate. Regenerate after changing project package metadata.
# Run with: sh package-deb.sh
# Requires dpkg-dev and binutils on a Debian/Ubuntu host matching the binary architecture.
# Override metadata with DEB_PACKAGE, DEB_VERSION, DEB_MAINTAINER, DEB_DESCRIPTION.
# DEB_DEPENDS adds dependencies for dynamically loaded libraries or external tools.
set -eu
export LC_ALL=C
fail() { printf '%s\n' "Debian package: $*" >&2; exit 1; }
for tool in dpkg dpkg-deb dpkg-shlibdeps readelf; do
    command -v "$tool" >/dev/null 2>&1 || fail "missing $tool; install dpkg-dev and binutils"
done
output_dir=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)
staged="$output_dir/package"
default_id=[PACKAGE_ID]
default_name=[PACKAGE_NAME]
default_version=[VERSION]
default_maintainer=[MAINTAINER]
default_description=[DESCRIPTION]
default_dependencies=[DEPENDENCIES]
executable=[EXECUTABLE]
name=${DEB_PACKAGE:-"$default_name"}
[ -n "$name" ] || name=$(printf '%s' "$default_id" | tr '[:upper:]' '[:lower:]')
version=${DEB_VERSION:-"$default_version"}
maintainer=${DEB_MAINTAINER:-"$default_maintainer"}
description=${DEB_DESCRIPTION:-"$default_description"}
extra_dependencies=${DEB_DEPENDS:-"$default_dependencies"}
[ -n "$maintainer" ] || fail 'set @linux package_maintainer or DEB_MAINTAINER to Name <email>'
cr=$(printf '\r')
single_line() {
    case "$2" in
        *'
'*|*"$cr"*) fail "$1 must be a single line" ;;
    esac
}
single_line name "$name"
single_line version "$version"
single_line maintainer "$maintainer"
single_line description "$description"
single_line dependencies "$extra_dependencies"
dpkg --validate-pkgname "$name"
dpkg --validate-version "$version"
binary="$staged/usr/bin/$executable"
[ -x "$binary" ] || fail "missing staged executable: $binary; build the application first"
machine=$(readelf -h "$binary" | sed -n 's/^ *Machine: *//p')
case "$machine" in
    'Advanced Micro Devices X86-64') architecture=amd64 ;;
    'Intel 80386') architecture=i386 ;;
    AArch64) architecture=arm64 ;;
    *) fail "unsupported ELF machine: $machine" ;;
esac
[ "$architecture" = "$(dpkg --print-architecture)" ] || fail "run packaging on a Debian/Ubuntu $architecture host"
work=$(mktemp -d)
trap 'rm -rf -- "$work"' EXIT
trap 'exit 1' HUP INT TERM
root="$work/root"
mkdir -p "$root/DEBIAN" "$work/debian"
cp -R "$staged/usr" "$root/usr"
find "$root" -type d -exec chmod 755 {} +
chmod 755 "$root/usr/bin/$executable"
desktop="$root/usr/share/applications/$default_id.desktop"
[ -f "$desktop" ] || fail "missing staged launcher: $desktop"
# Desktop files and icons are data files rather than executable launchers.
find "$root/usr/share" -type f -exec chmod 644 {} +
if command -v desktop-file-validate >/dev/null 2>&1; then
    desktop-file-validate "$desktop"
fi
cat > "$work/debian/control" <<EOF
Source: $name
Section: utils
Priority: optional
Maintainer: $maintainer

Package: $name
Architecture: any
Description: $description
EOF
# Resolve linked-library packages and minimum versions using the host package database.
# Missing dependency information is an error rather than silently producing an incomplete package.
dependencies=$(cd "$work" && dpkg-shlibdeps -O -e"$root/usr/bin/$executable")
dependencies=$(printf '%s\n' "$dependencies" | sed -n 's/^shlibs:Depends=//p')
if [ -n "$extra_dependencies" ]; then
    dependencies="${dependencies:+$dependencies, }$extra_dependencies"
fi
size=$(du -sk "$root/usr" | awk '{print $1}')
cat > "$root/DEBIAN/control" <<EOF
Package: $name
Version: $version
Section: utils
Priority: optional
Architecture: $architecture
Maintainer: $maintainer
Installed-Size: $size
Description: $description
EOF
if [ -n "$dependencies" ]; then
    printf 'Depends: %s\n' "$dependencies" >> "$root/DEBIAN/control"
fi
(cd "$root" && find usr -type f -print0 | sort -z | xargs -0 md5sum > DEBIAN/md5sums)
output="$output_dir/${name}_${version}_${architecture}.deb"
dpkg-deb --root-owner-group --build "$root" "$output"
printf 'Created %s\n' "$output"
